def proximity_kernel(Z, n_features=None):
    """Eq. (15)/(16): K = (1/d) Z Z^T, with d the number of features (not d*nbins)."""
    Z = np.asarray(Z, dtype=float)
    if n_features is None:
        raise ValueError("n_features (d) must be given: Z has d*nbins columns")
    return Z @ Z.T / float(n_features)

